        except (KeyError, TypeError, ValueError) as exc:
            raise PlatformReadError("alpha count response has no valid count") from exc

    def fetch_identity(self, *, recovery_probe: bool = False) -> dict[str, Any]:
        self.authenticate()
        response = self.request(
            "GET",
