"""Mutually exclusive historical and new-Alpha eligibility classification."""

from __future__ import annotations

from dataclasses import dataclass
from enum import Enum
from typing import Any, Mapping


class EligibilityStatus(str, Enum):
    SUBMIT_READY = "SUBMIT_READY"
    SUBMIT_READY_EXCEPT_DESCRIPTION = "SUBMIT_READY_EXCEPT_DESCRIPTION"
    STALE_CHECKS = "STALE_CHECKS"
    BASE_GATE_FAILED = "BASE_GATE_FAILED"
    SELF_CORR_FAILED = "SELF_CORR_FAILED"
    PROD_CORR_FAILED = "PROD_CORR_FAILED"
    DESCRIPTION_SCHEMA_UNKNOWN = "DESCRIPTION_SCHEMA_UNKNOWN"
    ALREADY_SUBMITTED = "ALREADY_SUBMITTED"
    SUBMISSION_PENDING = "SUBMISSION_PENDING"
    UNKNOWN_BLOCKED = "UNKNOWN_BLOCKED"


@dataclass(frozen=True)
class EligibilityDecision:
    status: EligibilityStatus
    reasons: tuple[str, ...] = ()


def _checks(row: Mapping[str, Any]) -> dict[str, str]:
    return {
        str(check.get("name") or check.get("check") or "").upper(): str(
            check.get("result") or check.get("status") or "UNKNOWN"
        ).upper()
        for check in row.get("checks", [])
        if isinstance(check, dict) and str(check.get("name") or check.get("check") or "").strip()
    }


def classify_alpha(row: Mapping[str, Any]) -> EligibilityDecision:
    status = str(row.get("platform_status") or "UNKNOWN").upper()
    if status not in {"UNSUBMITTED", "UNKNOWN", ""}:
        return EligibilityDecision(EligibilityStatus.ALREADY_SUBMITTED, (f"PLATFORM_{status}",))
    if bool(row.get("submission_pending")) or bool(row.get("uncertain_write")):
        return EligibilityDecision(EligibilityStatus.SUBMISSION_PENDING, ("SUBMISSION_PENDING",))
    if not bool(row.get("checks_fresh")):
        return EligibilityDecision(EligibilityStatus.STALE_CHECKS, ("CHECKS_STALE_OR_MISSING",))

    checks = _checks(row)
    base_failures = sorted(
        name
        for name, result in checks.items()
        if name not in {"SELF_CORRELATION", "PROD_CORRELATION", "PRODUCTION_CORRELATION", "DESCRIPTION"}
        and result in {"FAIL", "FAILED", "REJECTED"}
    )
    if base_failures:
        return EligibilityDecision(EligibilityStatus.BASE_GATE_FAILED, tuple(base_failures))
    if checks.get("SELF_CORRELATION") in {"FAIL", "FAILED", "REJECTED"}:
        return EligibilityDecision(EligibilityStatus.SELF_CORR_FAILED, ("SELF_CORRELATION",))
    prod = checks.get("PROD_CORRELATION", checks.get("PRODUCTION_CORRELATION", "MISSING"))
    if prod in {"FAIL", "FAILED", "REJECTED"} and not bool(row.get("prod_corr_exception_confirmed")):
        return EligibilityDecision(EligibilityStatus.PROD_CORR_FAILED, ("PROD_CORRELATION",))

    non_pass = sorted(name for name, result in checks.items() if result != "PASS")
    if non_pass and not (
        set(non_pass) <= {"PROD_CORRELATION", "PRODUCTION_CORRELATION"}
        and bool(row.get("prod_corr_exception_confirmed"))
    ):
        return EligibilityDecision(EligibilityStatus.UNKNOWN_BLOCKED, tuple(non_pass))
    if not checks:
        return EligibilityDecision(EligibilityStatus.UNKNOWN_BLOCKED, ("CHECKS_MISSING",))
    if bool(row.get("description_required")) and not bool(row.get("schema_known")):
        return EligibilityDecision(
            EligibilityStatus.DESCRIPTION_SCHEMA_UNKNOWN, ("DESCRIPTION_SCHEMA_UNKNOWN",)
        )
    if bool(row.get("description_required")) and not bool(row.get("description_valid")):
        return EligibilityDecision(
            EligibilityStatus.SUBMIT_READY_EXCEPT_DESCRIPTION,
            ("DESCRIPTION_REQUIRED",),
        )
    return EligibilityDecision(EligibilityStatus.SUBMIT_READY)

"""Shared immutable states for the description workflow."""

from __future__ import annotations

from enum import Enum


class DescriptionStatus(str, Enum):
    NOT_REQUIRED = "NOT_REQUIRED"
    REQUIRED = "REQUIRED"
    GENERATED = "GENERATED"
    VALIDATED = "VALIDATED"
    PATCH_PENDING = "PATCH_PENDING"
    PATCHED = "PATCHED"
    VERIFIED = "VERIFIED"
    FAILED = "FAILED"
    SCHEMA_UNKNOWN = "SCHEMA_UNKNOWN"


_TRANSITIONS: dict[DescriptionStatus, frozenset[DescriptionStatus]] = {
    DescriptionStatus.REQUIRED: frozenset(
        {DescriptionStatus.GENERATED, DescriptionStatus.SCHEMA_UNKNOWN, DescriptionStatus.FAILED}
    ),
    DescriptionStatus.GENERATED: frozenset(
        {DescriptionStatus.VALIDATED, DescriptionStatus.FAILED}
    ),
    DescriptionStatus.VALIDATED: frozenset(
        {DescriptionStatus.PATCH_PENDING, DescriptionStatus.FAILED}
    ),
    DescriptionStatus.PATCH_PENDING: frozenset(
        {DescriptionStatus.PATCHED, DescriptionStatus.VERIFIED, DescriptionStatus.FAILED}
    ),
    DescriptionStatus.PATCHED: frozenset(
        {DescriptionStatus.VERIFIED, DescriptionStatus.FAILED}
    ),
    DescriptionStatus.FAILED: frozenset(
        {DescriptionStatus.REQUIRED, DescriptionStatus.GENERATED}
    ),
    DescriptionStatus.SCHEMA_UNKNOWN: frozenset({DescriptionStatus.REQUIRED}),
    DescriptionStatus.NOT_REQUIRED: frozenset(),
    DescriptionStatus.VERIFIED: frozenset(),
}


def transition_description(
    current: DescriptionStatus, target: DescriptionStatus
) -> DescriptionStatus:
    if target is current:
        return current
    if target not in _TRANSITIONS[current]:
        raise ValueError(f"invalid description transition: {current.value} -> {target.value}")
    return target

"""Hard validation that prevents unsupported Description writes."""

from __future__ import annotations

import re
from dataclasses import dataclass

from .engine import DescriptionDraft
from .facts import DescriptionFacts
from .schema import DescriptionSchema


@dataclass(frozen=True)
class DescriptionValidation:
    valid: bool
    errors: tuple[str, ...]


def _get_path(payload: dict, path: tuple[str, ...]):
    value = payload
    for key in path:
        if not isinstance(value, dict) or key not in value:
            return None
        value = value[key]
    return value


def validate_description(
    draft: DescriptionDraft,
    facts: DescriptionFacts,
    schema: DescriptionSchema,
) -> DescriptionValidation:
    errors: list[str] = []
    text = draft.text
    low = text.lower()
    if draft.alpha_type != facts.alpha_type or schema.alpha_type != facts.alpha_type:
        errors.append("ALPHA_TYPE_SCHEMA_MISMATCH")
    if draft.facts_hash != facts.facts_hash:
        errors.append("FACTS_HASH_MISMATCH")
    if draft.schema_hash != schema.schema_hash:
        errors.append("SCHEMA_HASH_MISMATCH")
    if set(schema.required_sections) - set(draft.sections):
        errors.append("REQUIRED_SECTIONS_MISSING")
    if _get_path(draft.payload, schema.payload_path) != text:
        errors.append("PAYLOAD_PATH_MISMATCH")
    if len(text) < schema.min_length or (
        schema.max_length is not None and len(text) > schema.max_length
    ):
        errors.append("LENGTH_INVALID")
    if any(field.lower() not in low for field in facts.fields):
        errors.append("FIELD_CONSISTENCY_FAILED")
    if any(operator.lower() not in low for operator in facts.operators):
        errors.append("OPERATOR_CONSISTENCY_FAILED")
    if any(str(window) not in text for window in facts.windows):
        errors.append("WINDOW_CONSISTENCY_FAILED")
    if any(group.lower() not in low for group in facts.groups):
        errors.append("GROUP_CONSISTENCY_FAILED")
    if facts.direction.lower() not in low:
        errors.append("DIRECTION_CONSISTENCY_FAILED")
    if any(str(value).lower() not in low for value in facts.settings.values()):
        errors.append("SETTINGS_CONSISTENCY_FAILED")
    if re.search(r"\b(?:sharpe|fitness|returns?|correlation)\b.{0,24}(?:=|is|of)\s*[+-]?\d", text, re.I):
        errors.append("UNSUPPORTED_PERFORMANCE_CLAIM")
    if re.search(r"\b(?:todo|tbd|placeholder|null|none)\b|\[[a-z_ ]+\]", text, re.I):
        errors.append("PLACEHOLDER_DETECTED")
    if len(text) < 80 or re.fullmatch(r"\s*this is a (?:good|strong) alpha signal\.?s*", text, re.I):
        errors.append("GENERIC_DESCRIPTION")
    return DescriptionValidation(not errors, tuple(dict.fromkeys(errors)))

"""Schema-directed deterministic Description drafting."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any

from .facts import DescriptionFacts
from .models import DescriptionStatus
from .schema import DescriptionSchema


@dataclass(frozen=True)
class DescriptionDraft:
    alpha_type: str
    sections: dict[str, str]
    text: str
    payload: dict[str, Any]
    source: str
    facts_hash: str
    schema_hash: str
    status: DescriptionStatus = DescriptionStatus.GENERATED


def _set_path(path: tuple[str, ...], value: str) -> dict[str, Any]:
    root: dict[str, Any] = {}
    cursor = root
    for key in path[:-1]:
        child: dict[str, Any] = {}
        cursor[key] = child
        cursor = child
    cursor[path[-1]] = value
    return root


def _field_text(facts: DescriptionFacts) -> str:
    return ", ".join(
        f"{field} ({facts.field_metadata[field].get('description') or 'platform metadata field'})"
        for field in facts.fields
    )


def _settings_text(facts: DescriptionFacts) -> str:
    return ", ".join(f"{key}={value}" for key, value in sorted(facts.settings.items()))


def _known_sections(facts: DescriptionFacts) -> dict[str, str]:
    mechanism = str(facts.hypothesis.get("mechanism") or "the recorded mechanism")
    fields = _field_text(facts)
    operators = ", ".join(
        f"{name} ({facts.operator_definitions[name]})" for name in facts.operators
    )
    windows = ", ".join(str(value) for value in facts.windows) or "no time-series window"
    groups = ", ".join(facts.groups) or "no explicit grouping operator"
    settings = _settings_text(facts)
    if facts.alpha_type == "REGULAR":
        return {
            "hypothesis": f"The alpha tests whether {mechanism} predicts a relative cross-sectional response.",
            "data_rationale": f"The implemented expression uses {fields}; each field is identified by platform metadata.",
            "signal_construction": f"The expression applies {operators}, uses windows {windows}, and groups by {groups}.",
            "long_short_interpretation": f"The recorded direction is {facts.direction}; opposite signal values receive the opposite exposure.",
            "settings_rationale": f"The recorded simulation settings are {settings}; no unrecorded setting is assumed.",
            "risks_and_limitations": "Coverage gaps, reporting timing, turnover, concentration, regime change, and platform correlation checks can invalidate the hypothesis.",
        }
    if facts.alpha_type == "SELECTION":
        return {
            "selection_objective": f"The selection tests {mechanism} within the recorded simulation universe.",
            "selection_conditions": f"Selection conditions are exactly those in the expression using {operators}, windows {windows}, and group {groups}.",
            "economic_rationale": f"The selected inputs are {fields}, as identified by platform metadata.",
            "post_selection_signal": f"After selection, positions follow the recorded direction {facts.direction} with settings {settings}.",
            "risks_and_limitations": "Coverage, unstable membership, concentration, and platform correlation checks can block use.",
        }
    if facts.alpha_type == "COMBO":
        return {
            "component_rationale": f"The recorded components use {fields} to test {mechanism}.",
            "combination_method": f"The expression combines components with {operators}, windows {windows}, and group {groups}.",
            "incremental_information": "Incremental information is a hypothesis to be tested; no performance or correlation result is asserted.",
            "overlap_correlation_control_rationale": f"Overlap is controlled by platform SELF and PROD correlation checks; direction is {facts.direction} and settings are {settings}.",
            "risks_and_limitations": "Component overlap, unstable weights, coverage gaps, and unverified correlation can invalidate the combination.",
        }
    return {}


def build_deterministic_description(
    facts: DescriptionFacts, schema: DescriptionSchema
) -> DescriptionDraft:
    if schema.alpha_type != facts.alpha_type:
        raise ValueError("alpha type and schema do not match")
    sections = _known_sections(facts)
    if not sections:
        summary = (
            f"The recorded {facts.alpha_type} alpha tests {facts.hypothesis.get('mechanism')}; "
            f"it uses {_field_text(facts)}, operators {', '.join(facts.operators)}, "
            f"windows {list(facts.windows)}, groups {list(facts.groups)}, direction {facts.direction}, "
            f"and settings {_settings_text(facts)}. No performance result is asserted."
        )
        sections = {name: summary for name in schema.required_sections}
    missing = set(schema.required_sections) - set(sections)
    if missing:
        raise ValueError(f"renderer does not support required sections: {sorted(missing)}")
    text = "\n".join(
        f"{name.replace('_', ' ').title()}: {sections[name]}"
        for name in schema.required_sections
    )
    return DescriptionDraft(
        alpha_type=facts.alpha_type,
        sections=sections,
        text=text,
        payload=_set_path(schema.payload_path, text),
        source="deterministic",
        facts_hash=facts.facts_hash,
        schema_hash=schema.schema_hash,
    )

